3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Locale;
8	import java.util.Set;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
16	 * region code derived from the owner's postcode (see {@link Owner#regionOfPostcode(String)}, or
17	 * {@code UNKNOWN} when the postcode maps to no known region) and HASH8 is the first 8 upper-case hex
18	 * characters of the SHA-256 of the normalized telephone concatenated with the lastName (e.g.
19	 * {@code NSW-3F9A1C7E}). The customer code no longer carries any per-city sequence number. When the
20	 * computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is appended with
21	 * the smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSW-3F9A1C7E-2}). Runs after
22	 * {@link BuildOwner} builds the entity (so the telephone is already in canonical E.164 form) and
23	 * before {@link SaveOwner} persists it, mutating the built owner in place so the saved and returned
24	 * record carries the code. Every value derived from the customer code — the membership number, its
25	 * check digit and the {@link Owner#getLocality() locality} — follows from this region-and-hash
26	 * identity.
27	 */
28	public class AssignOwnerCustomerCode {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String region = Owner.regionOfPostcode(owner.getPostcode());
32	        if (region == null) {
33	            region = "UNKNOWN";
34	        }
35	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
36	        String base = region + "-" + hash8;
37	        owner.setCustomerCode(deduplicate(base, owner, ownerRepository));
38	    }
39	
40	    /**
41	     * The unique customer code for the owner: {@code base} when no other owner already carries it,
42	     * otherwise {@code base-<n>} with the smallest {@code n} of 2 or more that is not yet taken.
43	     * The owner is not yet persisted, so its own code is excluded by identity.
44	     */
45	    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
46	        Set<String> taken = new HashSet<>();
47	        for (Owner existing : ownerRepository.findAll()) {
48	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
49	                continue;
50	            }
51	            String code = existing.getCustomerCode();
52	            if (code != null) {
53	                taken.add(code);
54	            }
55	        }
56	        if (!taken.contains(base)) {
57	            return base;
58	        }
59	        int n = 2;
60	        while (taken.contains(base + "-" + n)) {
61	            n++;
62	        }
63	        return base + "-" + n;
64	    }
65	
66	    /**
67	     * The first 8 upper-case hex characters of the SHA-256 digest of {@code value}, taken over its
68	     * UTF-8 bytes — i.e. the first 4 digest bytes rendered as hex.
69	     */
70	    private static String sha256Hex8(String value) {
71	        try {
72	            byte[] digest = MessageDigest.getInstance("SHA-256")
73	                    .digest(value.getBytes(StandardCharsets.UTF_8));
74	            StringBuilder sb = new StringBuilder(8);
75	            for (int i = 0; i < 4; i++) {
76	                sb.append(String.format(Locale.ROOT, "%02X", digest[i]));
77	            }
78	            return sb.toString();
79	        }
80	        catch (NoSuchAlgorithmException ex) {
81	            throw new IllegalStateException("SHA-256 not available", ex);
82	        }
83	    }
84	}
