8	/**
9	 * Emits, via the dedicated {@code AUDIT} logger, both the human-readable audit line — recording the
10	 * new owner's id, its assigned {@code customerCode}, its {@code registrationDate}, its
11	 * {@code membershipLevel} and its {@code membershipNumber} — and, in addition, an immutable structured
12	 * {@link OwnerCreatedEvent} serialized as JSON ({@code {seq, ownerId, customerCode, membershipLevel,
13	 * event:'OWNER_CREATED'}}) whose {@code seq} increases monotonically across creates. Runs after
14	 * {@link SaveOwner} (so the id is populated) and before {@link RespondWithOwnerCreated}.
15	 *
16	 * <p>It reads no repository, but stays under the pipeline's {@code transaction} governance
17	 * so the create commits as a single boundary spanning {@code save} through {@code respond}
18	 * (the responder maps the entity's lazy relations); an ungoverned step here would split
19	 * that boundary.
20	 */
21	public class AuditOwnerCreated {
22	
23	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
24	
25	    public void service(@Val Owner owner) {
26	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
27	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
28	                owner.getMembershipLevel(), owner.getMembershipNumber());
29	        AUDIT.info(OwnerCreatedEvent.of(owner).toJson());
30	    }
31	}
