610	    /**
611	     * The American Soundex code for {@code name}: the retained first letter followed by up to three
612	     * digits mapping the remaining consonants (b/f/p/v→1, c/g/j/k/q/s/x/z→2, d/t→3, l→4, m/n→5, r→6),
613	     * right-padded with zeros to length four. Adjacent duplicate codes collapse; {@code h}/{@code w}
614	     * do not separate repeated codes while vowels (and {@code y}) do. Non-letters are ignored. Returns
615	     * {@code ""} when {@code name} is null or has no letters. Two last names that sound alike share a
616	     * code, which is how the identity key and soft-match group surnames phonetically.
617	     */
618	    public static String soundex(String name) {
619	        if (name == null) {
620	            return "";
621	        }
622	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
623	        if (letters.isEmpty()) {
624	            return "";
625	        }
626	        StringBuilder code = new StringBuilder();
627	        code.append(letters.charAt(0));
628	        char prev = soundexDigit(letters.charAt(0));
629	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
630	            char c = letters.charAt(i);
631	            if (c == 'H' || c == 'W') {
632	                continue; // ignored and does not separate repeated codes
633	            }
634	            char digit = soundexDigit(c);
635	            if (digit != '0' && digit != prev) {
636	                code.append(digit);
637	            }
638	            prev = digit; // a vowel resets prev so a later same code is emitted again
639	        }
640	        while (code.length() < 4) {
641	            code.append('0');
642	        }
643	        return code.toString();
644	    }
645	
646	    /** The Soundex digit for an upper-case letter, {@code '0'} for vowels and {@code h}/{@code w}. */
647	    private static char soundexDigit(char c) {
648	        switch (c) {
649	            case 'B': case 'F': case 'P': case 'V':
650	                return '1';
651	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
652	                return '2';
653	            case 'D': case 'T':
654	                return '3';
655	            case 'L':
656	                return '4';
657	            case 'M': case 'N':
658	                return '5';
659	            case 'R':
660	                return '6';
661	            default:
662	                return '0';
663	        }
664	    }
