666	    /**
667	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
668	     * national digits (everything after the country code) grouped in threes and space-separated —
669	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
670	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
671	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
672	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
673	     */
674	    public String getTelephoneDisplay() {
675	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
676	            return null;
677	        }
678	        String digits = this.telephone.substring(1);
679	        int countryCodeLength;
680	        if (digits.startsWith("61")) {
681	            countryCodeLength = 2;
682	        }
683	        else if (digits.startsWith("1")) {
684	            countryCodeLength = 1;
685	        }
686	        else {
687	            countryCodeLength = 2;
688	        }
689	        String countryCode = digits.substring(0, countryCodeLength);
690	        String national = digits.substring(countryCodeLength);
691	        StringBuilder display = new StringBuilder("+").append(countryCode);
692	        for (int i = 0; i < national.length(); i += 3) {
693	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
694	        }
695	        return display.toString();
696	    }
