540	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
541	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
542	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
543	     * digit from the right, subtracting 9 from any result over 9, and taking
544	     * {@code (10 - sum % 10) % 10}. Not persisted.
545	     */
546	    public Integer getCheckDigit() {
547	        if (this.customerCode == null) {
548	            return null;
549	        }
550	        int sum = 0;
551	        boolean dbl = true;
552	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
553	            char c = this.customerCode.charAt(i);
554	            if (c < '0' || c > '9') {
555	                continue;
556	            }
557	            int d = c - '0';
558	            if (dbl) {
559	                d *= 2;
560	                if (d > 9) {
561	                    d -= 9;
562	                }
563	            }
564	            sum += d;
565	            dbl = !dbl;
566	        }
567	        return (10 - (sum % 10)) % 10;
568	    }
