572	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone is
573	     * stored in canonical E.164 form and the email lower-cased; an absent telephone or email
574	     * contributes an empty segment, and the last name is reduced to its {@link #soundex(String)
575	     * Soundex} code. Two owners share an identity exactly when this 64-character hex value is equal.
576	     *
577	     * <p>This is the single key duplicate detection keys off: a create is rejected 409 when a
578	     * non-deleted owner already carries the same identity key (see {@code DetectOwnerDuplicate}).
579	     * Because the telephone participates in the key, two owners with the same last name and postcode
580	     * but different telephones no longer collide here — they are flagged as a soft match instead (see
581	     * {@code DetectOwnerPossibleDuplicate}). Derived at response time and not persisted.
582	     */
583	    public String getIdentityKey() {
584	        String telephone = keyPart(this.telephone);
585	        String email = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
586	        String input = telephone + "|" + email + "|" + soundex(this.lastName);
587	        return sha256Hex(input);
588	    }
