590	    private static String keyPart(String value) {
591	        return value == null ? "" : value;
592	    }
593	
594	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
595	    private static String sha256Hex(String value) {
596	        try {
597	            byte[] digest = MessageDigest.getInstance("SHA-256")
598	                    .digest(value.getBytes(StandardCharsets.UTF_8));
599	            StringBuilder sb = new StringBuilder(digest.length * 2);
600	            for (byte b : digest) {
601	                sb.append(String.format("%02x", b));
602	            }
603	            return sb.toString();
604	        }
605	        catch (NoSuchAlgorithmException ex) {
606	            throw new IllegalStateException("SHA-256 not available", ex);
607	        }
608	    }
